function roomBackdropMarkup(d,eventId='',showNpc=false){const room=roomTypes[d.rooms?.[`${d.floor}:${d.x},${d.y}`]],info=sceneModel(d,room,null),decoration=createRoomDecoration(room,d.map,d.floor,d.x,d.y),label=room?.name||'Stone Passage',event=eventId&&dungeonEvents[eventId],eventOverlay=event?`<span class="scene-event-object scene-event-object--${esc(event.id)}" data-label="${esc(event.title)}" aria-hidden="true"></span>`:'',landmark=info.landmark?`<span class="scene-landmark-object scene-landmark-object--${esc(info.landmark.id)}" aria-hidden="true"></span>`:'',npc=showNpc?`<span class="scene-npc-object" aria-hidden="true"></span>`:'',props=roomPropMarkup(decoration,state.settings?.spriteStyle==='ink'?'ink':'colored',false);return `<div class="scene scene--${esc(room?.id||'ordinary')} ${info.landmarkClass?`scene--${info.landmarkClass}`:''} scene-backdrop" role="img" aria-label="${esc(label)}. ${esc(info.description)}"><span class="scene-room-label">${esc(label).toUpperCase()}</span><div class="scene-view" aria-hidden="true"><i class="scene-ceiling"></i><i class="scene-side scene-side--left ${info.leftOpen?'is-open':'is-wall'}"></i><i class="scene-side scene-side--right ${info.rightOpen?'is-open':'is-wall'}"></i><i class="scene-far ${info.front?'is-open':'is-wall'}"></i><i class="scene-floor"></i><i class="scene-light"></i><div class="room-props" data-decoration-seed="${decoration.seed}">${props}</div>${landmark}${eventOverlay}${npc}</div></div>`}
