function npcLine(id){const visits=state.town.npcProgress?.[id]||0,d=state.dungeon,c=state.career||{};if(id==='kobold-trader'){const lines=['Pip taps the ledger. “I have put you down as a returning customer and a possible source.”','Pip weighs the Condensed Stink jar at arm’s length. “This is a premium distance.”','Pip notices the deeper-floor dust. “That grades as old inventory.”','Pip checks your spoon. “Official marks improve resale. Not by much.”','Pip turns a page. “The ledger remembers the trade even if I do not.”','Pip has begun labeling a shelf “objects with unclear obligations.”','Pip offers a deal, then revises it after looking at the item.'];if(d.floor>=3)return 'Pip flips to a new page. “Deeper floors have better merchandise and worse liability.”';return lines[visits%lines.length]}if(id==='lost-surveyor'){const lines=['Nell compares her map to the wall. “The wall appears to have moved, but only on paper.”','Nell has measured the corridor twice. Both measurements are correct.','Nell asks whether you have seen a warm wall. She has marked it with a careful circle.','Nell says the stairs are impossible to survey because they keep being stairs.','Nell offers a tonic and a map with one apologetic blank area.','Nell has started numbering the same corridor in two directions.','Nell records your return as “successful, subject to geometry.”'];if(d.floor>=2)return visits%2?'Nell marks the impossible geometry as “expected variance.”':'Nell is relieved. “I found the lower stair. It was below me.”';return lines[visits%lines.length]}return dungeonNpcs[id]?.line||'The visitor gives an unhelpful nod.'}
function marketNpcLine(market){const goods=groupedInventory().filter(entry=>['trade-good','junk'].includes(entry.item.category)),high=goods.find(entry=>marketDemand(entry.id).state==='high'),low=goods.find(entry=>marketDemand(entry.id).state==='low');if(countItem('air-freshener'))return 'Juniper: “I stock it. I am not asking what happened.”';if(countItem('condensed-stink'))return 'Juniper: “Please keep that jar upright.”';if(countItem('bad-seed'))return 'Juniper: “Those seeds are selling. I have elected not to ask why.”';if(high)return `Juniper: “I can actually use those ${high.item.name.toLowerCase()}s today.”`;if(low)return `Juniper: “Everybody brought me ${low.item.name.toLowerCase()}s this week.”`;if(goods.some(entry=>['rare','strange'].includes(entry.item.rarity)))return 'Juniper squints at the rare goods. “Where did you even get this?”';if((state.career?.marketCyclesSeen||0)>4)return 'Juniper: “Another expedition, another category nobody asked me to price.”';if((state.career?.strangeItemsFound||0)>0)return 'Juniper: “I have stopped putting the unusual things near the till.”';return ['Juniper checks the ledger. The market is behaving within policy.','Juniper has labeled a drawer “probably safe.”','Juniper: “If it fits on the scale, I can price it.”','Juniper turns a Goose Feather over. “These are becoming a situation.”','Juniper: “I am not taking responsibility for the smell.”'][market.cycle%5]}
function innNpcLine(full){const injured=state.player.hp<=Math.ceil(state.player.maxHp/2),eventCount=state.career?.innEventsTriggered||0,last=transactionFeedback||'',effects=innEffectSummary();if(full)return ['You’re fine. Go away.','You have all your hit points. This is a lodging establishment, not a hobby.','The bed is available to someone with a problem.','You appear rested enough to argue.'][eventCount%4];if(injured)return ['You look terrible. The room is ready.','Sit down before you fall down. I just swept.','That is a lot of damage to bring indoors.','I’ll put fresh sheets on the bed. Probably.'][eventCount%4];if(last.includes('WELL RESTED'))return 'Apparently that room agreed with you.';if(effects.length)return 'Your room seems to have done something useful.';return ['The room is quiet, and the blankets are accounted for.','The coffee is fresh. The cup is clean. This is a good day.','I changed the sheets. I will not be taking questions.','Breakfast is available. The eggs have paperwork.','Someone left a coin under the bed. I put it on your bill, then removed it.','The mattress only squeaks on the third turn.'][eventCount%6]}
function townNpcLine(id){const p=state.player,c=state.career||{},flags=state.dungeon.eventFlags||{},held=new Set(state.inventory.map(entry=>entry.id));if(id==='clerk'){if(flags['odor-sample-collected'])return 'Linna has added “air sample” to a new folder. The folder is stored at arm’s length.';if((c.heartAttacksDefeated||0)>0)return 'Linna has classified the flying heart as “anatomical, airborne, and not a bird.”';if(flags['spoons-counted'])return 'Linna has attached a second page to the spoon report. It is mostly tallies.';if((c.deepestFloor||state.dungeon.deepestFloor||1)>=3)return 'Linna has added a lower-depth annex to the filing cabinet. It is already full.';const lines=['Linna files new reports by the thing they are least likely to explain.','Linna has created a form for objects that appear to be food.','Linna says the latest stair report is complete except for the stairs.','Linna has marked the warm wall “recurring, but not scheduled.”','Linna has started a folder called “forms that became evidence.”','Linna says municipal classification may take several business days underground.','Linna asks whether the room full of spoons has a custodian.'];return p?.class==='Wizard'?'Linna has filed your magical qualifications under “unusual lighting.”':lines[(c.questsCompleted||0)%lines.length]}if(id==='shopkeeper'){if(held.has('condensed-stink'))return 'Juniper eyes the sealed jar. “I can use that. From over there.”';if(held.has('bad-seed'))return 'Juniper has a buyer for Bad Seeds. She will not say what they do.';if(held.has('air-freshener'))return 'Juniper approves of the Air Freshener label and nothing else about it.';if((c.strangeItemsFound||0)>0)return 'Juniper has started pricing strange goods by how warm they feel.';if(p?.class==='Rogue')return 'Juniper respects a good bargain and has adjusted nothing.';const lines=['Juniper says the market is steady, which is not the same as good.','Juniper has set aside a shelf for goods she does not want to identify.','Juniper says every item has a buyer. Some buyers are not local.','Juniper checks the price ledger, then checks who is watching.','Juniper calls the latest trade good “seasonal.” It is a spoon.','Juniper asks if you found anything that does not smell like a basement.'];return lines[(c.marketCyclesSeen||c.itemsFound||0)%lines.length]}if(id==='innkeeper'){if(p&&p.hp<=Math.ceil(p.maxHp/2))return 'Sal puts a clean towel on the counter. “You look terrible.”';if(state.town.innEffects?.lastEvent==='well-rested')return 'Sal says the room seems to have agreed with you.';if(state.town.innEffects?.lastEvent==='squeaky-bed')return 'Sal says the bed only squeaks when someone is in it.';if((c.deaths||0)>0)return 'Sal moved you closer to the stairs. “It seemed practical.”';const lines=['Sal says the coffee is free because the pot was already on.','Sal insists the towels are clean. They are folded with great confidence.','Sal has stopped asking what makes the pipes knock.','Sal says the rooms are quiet unless you listen for them.','Sal has placed a coin on the desk. It belongs to no one in particular.','Sal recommends sleeping before the next unreasonable floor.'];return lines[(c.innEventsTriggered||0)%lines.length]}return ''}
function itemPill(id){const item=items[id];return item?`<span class="rarity rarity-${item.rarity||'common'}">${esc(item.name)} · ${esc(item.rarity||'common')}</span>`:'<span class="subtle">Empty</span>'}
function itemMods(item){const mods=Object.entries(item.modifiers||{}).map(([key,value])=>`${value>=0?'+':''}${value} ${statNames[key]||key}`),effects=Object.entries(item.effects||{}).map(([key,value])=>({vsGoose:`+${value} damage vs Kung Fungoose`,lootBonus:`+${Math.round(value*100)}% rare/Strange find chance`,fireResistance:`Fire resistance +${value}`,retreatBonus:`${value>=0?'+':''}${value}% escape chance`,postCombatHeal:`${Math.round(value*100)}% chance to recover 1 HP after combat`,buyDiscount:`${Math.round(value*100)}% lower shop prices`,sellBonus:`${Math.round(value*100)}% higher sale value`,duckSense:'Reveals an additional clue near the duck.',hazardReduction:`Reduces hazard damage by ${value}`,statusResistance:`${Math.round(value*100)}% status-effect resistance`,vsTags:`Bonus damage: ${Object.entries(value).map(([tag,n])=>`+${n} vs ${tag}`).join(', ')}`}[key]||`${key}: ${value}`)),use=item.effect?.type==='heal'?`Restores ${item.effect.amount} HP`:item.effect?.type==='combat-tool'?`Specially effective against ${item.effect.targetTags?.join(', ')||'some enemies'}`:item.effect?.type==='buff'?`Temporary ${item.effect.stat||'combat'} benefit`:'';return [...mods,...effects,use].filter(Boolean).join(' · ')||'No stat change'}
function compareMarkup(id){const item=items[id],c=compareEquipment(id);if(!item?.slot||!c)return '';const current=c.current?`${esc(c.current.name)} (${slotNames[item.slot]})`:'Nothing equipped';const deltas=Object.entries(c.deltas).map(([k,v])=>`<span class="delta ${v>0?'positive':'negative'}">${v>0?'+':''}${v} ${statNames[k]||k}</span>`).join(' ');return `<div class="comparison"><small>Current: ${current}</small><div>${deltas||'No stat difference'}</div></div>`}
function showItemDetails(id){const item=items[id];if(!item)return;modal.innerHTML=`<div class="modal-layer"><section class="title-card item-detail-card"><div class="service-nav"><b>${esc(item.name)}</b><button data-modal="close">Close</button></div><p class="eyebrow">${esc(item.rarity||'common')} · ${esc(item.category||'item')}</p><p>${esc(item.flavor||'No additional notes.')}</p><p>${esc(itemMods(item))}</p>${compareMarkup(id)}<button data-modal="close">Done</button></section></div>`}
function inventoryViewMarkup(inDungeon=false){const inventory=groupedInventory(),slots=EQUIPMENT_SLOTS;return `${header()}<p class="eyebrow">${inDungeon?'Below town · Pack check':'Your paperwork'}</p><h1 class="section-title">${inDungeon?'Inventory & Gear':'Character & Equipment'}</h1><section class="panel">${stats()}<p>STR ${state.player.str} · AGI ${state.player.agi} · MND ${state.player.mind} · VIT ${state.player.vit} · ATK ${state.player.attack} · DEF ${state.player.defense} · MP ${state.player.mp}/${state.player.maxMp}</p><p class="subtle">XP to next level: ${Math.max(0,state.player.level*25-state.player.xp)}</p></section><section class="panel"><h2>Equipment</h2><div class="slot-grid">${slots.map(slot=>`<div class="slot"><small>${slotNames[slot]}</small><div>${state.equipment[slot]?itemPill(state.equipment[slot]):'<span class="subtle">Empty</span>'}</div>${state.equipment[slot]?`<button data-unequip="${slot}" ${state.combat?'disabled title="Equipment changes are disabled during combat"':''}>Unequip</button>`:''}</div>`).join('')}</div></section><section class="panel"><h2>Pack · ${inventoryUsed()}/${inventoryCapacity()} slots</h2>${inventory.map(({id,item,quantity,provenance})=>{const reserved=questReservedQuantity(id),canSell=canRemoveItem(id,1);return `<article class="item-row"><div>${itemPill(id)} × ${quantity}<p>${esc(item.flavor||'')}</p>${provenance?.length?`<small class="provenance">${esc(provenance.map(p=>`${p.sourceName||p.sourceType||'Found'} · Level ${p.acquiredFloor||'?'}`).join(' · '))}</small>`:''}${item.slot?`<p>${esc(itemMods(item))}</p>${compareMarkup(id)}`:''}${reserved&&!canSell?`<small class="unavailable-copy">${reserved} reserved for an active quest</small>`:''}</div><div class="row item-actions">${item.slot?`<button data-equip="${id}" ${state.combat||item.classes&&!item.classes.includes(state.player.class)?'disabled':''}>Equip</button>`:''}${item.effect?`<button data-use="${id}">Use</button>`:''}${!inDungeon&&!item.questItem?`<button data-sell="${id}" ${!canSell||Object.values(state.equipment).includes(id)?'disabled':''}>Sell · ${salePrice(id)}g</button>`:''}</div></article>`}).join('')||'<p>Nothing carried.</p>'}</section>${message?`<p class="notice">${esc(message)}</p>`:''}<button ${inDungeon?'data-action="close-inventory"':'data-go="town"'}>${inDungeon?'Back to dungeon':'Back to town'}</button>`}
function questCardMarkup(quest,status,progress=0){const reward=`${quest.reward.gold}g / ${quest.reward.xp} XP${quest.reward.item?` / ${items[quest.reward.item]?.name||'item'}`:''}`,stateLabel={available:'Available',active:'Active',ready:'Ready to Turn In',completed:'Completed'}[status];return `<article class="quest quest--${status}"><div>${quest.chain?`<small class="eyebrow">${esc(quest.chain)} · Step ${quest.step}</small>`:''}<h3>${esc(quest.title)}</h3><p>${esc(quest.description)}</p><small class="subtle">${esc(quest.giver)} · Reward ${reward}</small>${status==='active'||status==='ready'?`<p>${status==='ready'?'Objective complete':`Progress ${progress}/${quest.count}`}</p>`:''}</div><div class="quest-actions"><span class="pill quest-status quest-status--${status}">${stateLabel}</span>${status==='available'?`<button data-quest="${quest.id}" ${state.quests.active.length>=5?'disabled':''}>Accept</button>`:''}${status==='ready'?`<button class="primary" data-turn-in="${quest.id}">Turn In</button>`:''}</div></article>`}
function achievementUnlockText(){const names=(state.dungeon.achievementNotices||[]).splice(0);if(names.length)persist();return names.length?`Achievement unlocked: ${names.join(', ')}.`:''}
function careerScreen(kind){const c=state.career||{},unlocked=state.achievements?.unlocked||{};if(kind==='achievements')return `${header()}<p class="eyebrow">Local records</p><h1 class="section-title">Achievements</h1><section class="panel">${achievements.map(a=>`<article class="quest"><div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p></div><span class="pill">${unlocked[a.id]?'Earned':'Unrecorded'}</span></article>`).join('')}</section><button data-go="town">Back to town</button>`;const groups={Adventure:[['deepestFloor','Deepest floor'],['successfulReturns','Successful returns'],['interruptedReturns','Interrupted returns'],['combatRetreats','Combat retreats'],['deaths','Defeats'],['rescues','Office rescues'],['questsCompleted','Quests completed']],Combat:[['enemiesDefeated','Enemies defeated'],['damageDealt','Damage dealt'],['damageTaken','Damage taken'],['gooseAttacks','Times attacked by geese']],Economy:[['goldEarned','Gold earned'],['goldSpent','Gold spent'],['itemsFound','Items found']],Research:[['strangeItemsFound','Strange items found'],['ducksEncountered','Ducks encountered'],['spoonsCollected','Spoons collected'],['mushroomsCollected','Mushrooms collected'],['vendingShakes','Vending machine shakes']]};return `${header()}<p class="eyebrow">This character’s local history</p><h1 class="section-title">Statistics</h1>${Object.entries(groups).map(([name,rows])=>`<section class="panel"><h2>${name}</h2><div class="career-grid">${rows.map(([key,label])=>`<div><span>${label}</span><b>${c[key]||0}</b></div>`).join('')}</div></section>`).join('')}<button data-go="town">Back to town</button>`}
function classPreview(className,stats){const rolled=stats||rollStartingStats(className),resources=deriveStartingResources(className,rolled),gear=['rusty-sword','patched-coat'].map(id=>items[id]),mods=gear.reduce((sum,item)=>{for(const [key,value] of Object.entries(item.modifiers||{}))sum[key]=(sum[key]||0)+value;return sum},{});return `<div class="creation-stats"><span><b>STR</b> ${rolled.str}</span><span><b>AGI</b> ${rolled.agi}</span><span><b>MIND</b> ${rolled.mind}</span><span><b>VIT</b> ${rolled.vit}</span><span><b>HP</b> ${resources.hp+(mods.hp||0)}</span><span><b>MP</b> ${resources.mp+(mods.mp||0)}</span></div>`}
function groupedInventory(){const groups=new Map();for(const entry of state.inventory.filter(e=>e.quantity>0)){const old=groups.get(entry.id)||{quantity:0,provenance:[]};old.quantity+=entry.quantity;if(entry.provenance)old.provenance.push(entry.provenance);groups.set(entry.id,old)}return [...groups].map(([id,data])=>({item:items[id],id,quantity:data.quantity,provenance:data.provenance})).filter(x=>x.item)}
function titleScreen(){screen='title';app.innerHTML=`<section class="title-screen"><div class="title-card">${gameMasthead('h1','game-masthead--hero')}<p class="subtle">The town has a procedure for this. The hole does not.</p><div class="button-stack">${hasSave()?'<button class="primary" data-action="continue">Continue</button>':''}<button class="primary" data-action="new">New Game</button><button data-action="settings">Settings</button><button data-action="help">About / Help</button></div><p class="footer">A turn-based descent · Best played one careful step at a time</p></div></section>`}
function mapCellMarkup(d,floor,x,y){const k=`${x},${y}`,seen=d.explored.includes(`${floor}:${k}`)||d.explored.includes(k),player=x===d.x&&y===d.y,wall=wallAt(d,x,y),landmark=seen&&d.landmarks.find(l=>l.floor===d.floor&&l.x===x&&l.y===y),up=seen&&x===d.map.upStairs[0]&&y===d.map.upStairs[1],down=seen&&x===d.map.downStairs[0]&&y===d.map.downStairs[1],visitor=seen&&d.npcs.find(n=>n.floor===d.floor&&!n.resolved&&n.x===x&&n.y===y),tag=seen&&d.rooms[`${floor}:${k}`]&&d.rooms[`${floor}:${k}`]!=='ordinary',edges=seen&&!wall?`${wallAt(d,x,y-1)?'wall-n ':''}${wallAt(d,x+1,y)?'wall-e ':''}${wallAt(d,x,y+1)?'wall-s ':''}${wallAt(d,x-1,y)?'wall-w ':''}`:'',mark=player?'P':up?'↑':down?'↓':landmark?.id==='warm-wall'?'!':landmark?'L':visitor?'N':tag?'R':'',title=wall&&seen?'Known wall':landmark?.label|| (visitor?'Known visitor':tag?'Special room':seen?`Cell ${x}, ${y}${up?' · stairs up':''}${down?' · stairs down':''}`:'Unexplored');return `<i class="cell ${seen?'seen':''} ${wall&&seen?'known-wall':''} ${player?'player':''} ${up?'stairs-up':''} ${down?'stairs-down':''} ${landmark?'landmark':''} ${edges}" title="${esc(title)}" aria-hidden="true">${mark}</i>`}
function renderStoreScreen(){const stock=storeStock(),market=marketState(),coreIds=new Set(['healing-tonic','rusty-sword','leather-armor']),core=stock.filter(item=>coreIds.has(item.id)),rotating=stock.filter(item=>!coreIds.has(item.id)),equipped=new Set(Object.values(state.equipment)),sell=groupedInventory().filter(({id,item,quantity})=>!item.questItem&&!item.keyItem&&!equipped.has(id)&&quantity>questReservedQuantity(id)&&canRemoveItem(id,1));const buyRows=list=>list.map(item=>{const restricted=item.classes&&!item.classes.includes(state.player.class),poor=state.town.gold<buyPrice(item.id);return `<article class="shop-row"><button class="shop-item-name" data-inspect="${item.id}"><b>${esc(item.name)}</b><small class="rarity rarity-${item.rarity||'common'}">${esc(item.rarity||'common')}</small><small>${esc(itemMods(item))}</small></button><button class="shop-buy" data-buy="${item.id}" ${poor||restricted?'disabled':''}>Buy · ${buyPrice(item.id)}g</button></article>`}).join('');const sellRows=sell.map(({id,item,quantity})=>{const amount=quantity-questReservedQuantity(id),demand=marketDemand(id),sale=salePrice(id);return `<article class="shop-row"><div class="shop-item-name"><button class="shop-item-title" data-inspect="${id}">${esc(item.name)}</button><b>× ${amount}</b><small class="market-demand market-${demand.state}">${esc(demand.label)}</small><small>${sale}g each</small></div><div class="shop-actions"><button data-sell="${id}">Sell 1 · ${sale}g</button>${amount>1?`<button data-sell-all="${id}">Sell All · ${amount*sale}g</button>`:''}</div></article>`}).join('');return `${header()}${townStatus()}<section class="town-service store-service"><div class="town-service-heading">${townArtMarkup('general-store','▤',true)}<div><p class="eyebrow">TOWN · JUNIPER’S GENERAL STORE</p><h1 class="section-title">The General Store</h1></div><small class="juniper-line">${esc(marketNpcLine(market))}</small></div><div class="service-tabs store-tabs" role="tablist" aria-label="Store mode"><button role="tab" aria-selected="${storeMode==='buy'}" class="${storeMode==='buy'?'is-selected':''}" data-store-mode="buy">BUY</button><button role="tab" aria-selected="${storeMode==='sell'}" class="${storeMode==='sell'?'is-selected':''}" data-store-mode="sell">SELL</button></div><p class="market-cycle-note">Cycle ${market.cycle} · Stock changes after a successful expedition.</p>${storeMode==='buy'?`<section class="store-stock"><h2>Core Stock</h2>${buyRows(core)}<h2>Rotating Stock</h2>${buyRows(rotating)}</section>`:`<section class="store-stock" aria-live="polite">${sellRows||'<p class="compact-empty">Juniper looks through your bag. Nothing here I can buy.</p>'}</section>`}</section>`}
function innResultMarkup(){if(!transactionFeedback)return '';if(transactionFeedback.includes('Spent 5g')){const event=innEvents[state.town.innEffects?.lastEvent],effect=event?.effect;let benefit='';if(effect?.type==='xp-bonus')benefit=`+${effect.percent}% combat XP · next ${effect.battles} battles`;else if(effect?.type==='temporary')benefit=`${effect.name} +${effect.value} · ${effect.encounters} encounters`;else if(effect?.type==='item')benefit=`${items[effect.item]?.name||'Item'} added to your pack`;else if(effect?.type==='gold')benefit=`${effect.amount>0?'+':''}${effect.amount||0} gold`;return `<section class="service-result inn-result" role="status" aria-live="polite"><b>REST COMPLETE</b><p>Restored to full health and MP. Spent 5g.</p>${event?`<div class="service-result-event"><strong>${esc(event.name)}</strong>${benefit?`<small>${esc(benefit)}</small>`:''}<p>${esc(event.description)}</p></div>`:''}</section>`}return `<p class="service-result" role="status" aria-live="polite">${esc(transactionFeedback)}</p>`}
function renderInnScreen(){const full=state.player.hp>=state.player.maxHp&&state.player.mp>=state.player.maxMp,poor=state.town.gold<5,effects=innEffectSummary();return `${header()}${townStatus()}<section class="town-service inn-service"><div class="town-service-heading">${townArtMarkup('inn','⌂',true)}<div><p class="eyebrow">TOWN · THE LANTERN & LEDGER</p><h1 class="section-title">The Inn</h1></div><small>Sal: “${esc(innNpcLine(full))}”</small></div><div class="inn-vitals"><span>HP <b>${state.player.hp}/${state.player.maxHp}</b></span><span>MP <b>${state.player.mp}/${state.player.maxMp}</b></span><span>REST <b>5g</b></span></div>${effects.length?`<p class="inn-effects">${effects.map(esc).join(' · ')}</p>`:''}<button class="primary inn-rest-button" data-action="rest" ${full||poor?'disabled':''}>REST — 5g</button>${full?'<small class="unavailable-copy">Already fully rested. No charge.</small>':poor?'<small class="unavailable-copy">You need 5g for a room.</small>':''}${innResultMarkup()}</section>`}
function renderQuestScreen(){const available=state.quests.available.map(id=>quests[id]).filter(Boolean),active=state.quests.active.map(entry=>({quest:quests[entry.id],...questStatus(entry.id)})).filter(entry=>entry.quest),ready=active.filter(entry=>entry.status==='ready'),inProgress=active.filter(entry=>entry.status==='active'),completed=state.quests.completed.map(id=>quests[id]).filter(Boolean),groups={ready,active:inProgress,available,history:completed};if(!questMode)questMode=ready.length?'ready':inProgress.length?'active':available.length?'available':'history';const labels={ready:`Ready · ${ready.length}`,active:`Active · ${inProgress.length}`,available:`Available · ${available.length}`,history:`History · ${completed.length}`},entries=groups[questMode]||[];return `${header()}${townStatus()}<section class="town-service"><div class="town-service-heading">${townArtMarkup('quest-board','▧',true)}<div><p class="eyebrow">TOWN · NOTICE BOARD</p><h1 class="section-title">Quest Board</h1></div><small>${esc(townNpcLine('clerk'))}</small></div><div class="service-tabs quest-tabs" role="tablist" aria-label="Quest status">${Object.keys(groups).map(key=>`<button role="tab" aria-selected="${questMode===key}" class="${questMode===key?'is-selected':''}" data-quest-mode="${key}">${labels[key]}</button>`).join('')}</div><section class="quest-list" aria-live="polite">${entries.map(entry=>questMode==='active'||questMode==='ready'?questCardMarkup(entry.quest,entry.status,entry.progress):questCardMarkup(entry,questMode==='available'?'available':'completed')).join('')||`<p class="compact-empty">${{ready:'No quests are ready to turn in.',active:'No active quests.',available:'No new notices.',history:'No completed work on file.'}[questMode]}</p>`}</section>${message&&message!=='The town has posted new notices. The hole remains open.'?`<p class="notice" role="status">${esc(message)}</p>`:''}</section>`}
function compatibleSlotItems(slot){return [...new Set(state.inventory.map(entry=>entry.id))].filter(id=>items[id]?.slot===slot&&canEquipItem(id,slot))}
function renderGearSlotView(slot,inDungeon=false){const label=slotNames[slot]||'Equipment',currentId=state.equipment[slot],current=items[currentId],candidates=compatibleSlotItems(slot).filter(id=>id!==currentId);return `${header()}${townStatus(inDungeon)}<section class="town-service gear-slot-service"><div class="gear-slot-sticky"><button class="gear-back" data-gear-back aria-label="Back to Gear">← Back</button><span>${inDungeon?'Inventory & Gear':'Character'} · ${esc(label)}</span></div><div class="town-service-heading"><span class="service-emblem" aria-hidden="true">◈</span><div><p class="eyebrow">EQUIPMENT SLOT</p><h1 class="section-title">${esc(label)} Gear</h1></div></div><section class="gear-current"><small>CURRENT</small>${current?`<b>${esc(current.name)}</b><span>${esc(itemMods(current))}</span><button data-unequip="${slot}" ${state.combat?'disabled':''}>Unequip</button>`:'<b>Nothing</b>'}</section><h2 class="gear-available-heading">Available</h2><div class="gear-candidates">${candidates.map(id=>{const item=items[id],comparison=compareEquipment(id),changes=Object.entries(comparison?.deltas||{}).map(([key,value])=>`<span class="delta ${value>0?'positive':'negative'}">${value>0?'↑':'↓'} ${value>0?'+':''}${value} ${statNames[key]||key}</span>`).join('');return `<article class="gear-candidate"><div><button class="shop-item-title" data-inspect="${id}">${esc(item.name)}</button><small>${esc(itemMods(item))}</small>${changes?`<div class="gear-comparison">${changes}</div>`:'<small class="subtle">No stat changes</small>'}</div><button class="gear-equip" data-equip="${id}" ${state.combat||!canEquipItem(id,slot)?'disabled':''}>Equip</button></article>`}).join('')||`<p class="compact-empty">No other ${esc(label)} gear in your pack.</p>`}</div>${message&&!message.startsWith('The town has posted')?`<p class="notice" role="status">${esc(message)}</p>`:''}</section>`}
